import {test,expect} from '@playwright/test';
import {PDFDocument,StandardFonts,degrees} from 'pdf-lib';
import fontkit from '@pdf-lib/fontkit';
import * as mupdf from 'mupdf';
import fs from 'node:fs/promises';
async function fixture({subset=true,mixed=false,rotation=0}={}){const d=await PDFDocument.create();d.registerFontkit(fontkit);const font=await d.embedFont(await fs.readFile('C:/Windows/Fonts/timesi.ttf'),{subset});const p=d.addPage([595,842]);p.drawText('Original editable text',{x:60,y:720,size:23,font});if(mixed){const bold=await d.embedFont(await fs.readFile('public/fonts/bold.ttf'),{subset});p.drawText('BOLD',{x:60,y:650,font:bold,size:17});p.drawText('small',{x:150,y:650,font,size:11});}p.setRotation(degrees(rotation));return Buffer.from(await d.save());}
async function upload(page,bytes){await page.goto('/');await page.locator('#file').setInputFiles({name:'native-font.pdf',mimeType:'application/pdf',buffer:bytes});await expect(page.locator('#busy')).toBeHidden();await expect(page.locator('#document')).toBeVisible();await page.locator('#edit').click();await page.locator('[data-native="0"]').click();}
async function edit(page,text){await page.locator('#proptext').fill(text);await page.locator('#proptext').blur();}
async function exported(page){await page.locator('#export').click();const event=page.waitForEvent('download');await page.locator('#downloadnow').click();const d=await event;return fs.readFile(await d.path());}
function read(bytes){const doc=mupdf.Document.openDocument(new Uint8Array(bytes),'application/pdf'),p=doc.loadPage(0),st=p.toStructuredText();const chars=[];st.walk({onChar(c,origin,f,size){chars.push({c,font:f.getName(),size});}});const text=st.asText();st.destroy();p.destroy();doc.destroy();return {text,chars};}
test('subset embedded italic font and 23pt are preserved with selectable text',async({page})=>{await upload(page,await fixture());await expect(page.locator('#propsize')).toHaveValue('23');await edit(page,'editable text');await expect(page.locator('#fontstatus')).toContainText('gömülü font');await expect(page.locator('#overlay image')).toBeVisible();await page.screenshot({path:'test-results/original-font.png'});const bytes=await exported(page),r=read(bytes);expect(r.text).toContain('editable text');expect(r.text).not.toContain('Original');expect(r.chars.every(c=>/TimesNewRomanPS-ItalicMT/.test(c.font))).toBe(true);expect(r.chars.every(c=>Math.abs(c.size-23)<.01)).toBe(true);});
test('full embedded font accepts new Turkish glyphs and remains original font',async({page})=>{await upload(page,await fixture({subset:false}));await edit(page,'Çağrı Şen İĞÜŞÖÇ ıüğöç');await expect(page.locator('#fontstatus')).toContainText('korunuyor');const r=read(await exported(page));expect(r.text).toContain('Çağrı Şen');expect(r.chars.every(c=>/Italic/.test(c.font)&&Math.abs(c.size-23)<.01)).toBe(true);});
test('missing subset glyphs block export until user explicitly chooses fallback',async({page})=>{await upload(page,await fixture());await edit(page,'Yeni ĞİŞ');await expect(page.locator('#fontstatus')).toContainText('karakterler yok');await page.locator('#export').click();await page.locator('#downloadnow').click();await expect(page.locator('#toast')).toContainText('karakterler yok');await expect(page.locator('#modal')).toBeVisible();await page.locator('#closemodal').click();await page.locator('#fontmode').selectOption('noto');await expect(page.locator('#fontstatus')).toContainText('Özgün PDF fontu kullanılmıyor');const r=read(await exported(page));expect(r.text).toContain('Yeni ĞİŞ');expect(r.chars.every(c=>/NotoSans-(Regular|Italic)/.test(c.font))).toBe(true);});
test('upload original full font restores absent glyphs and survives project save and reopen',async({page})=>{await upload(page,await fixture());await edit(page,'Çağrı Şen');await expect(page.locator('#fontstatus')).toContainText('karakterler yok');await page.locator('#fontfile').setInputFiles('C:/Windows/Fonts/timesi.ttf');await expect(page.locator('#fontstatus')).toContainText('Yüklenen font');const event=page.waitForEvent('download');await page.locator('#project').click();const saved=await event,project=await fs.readFile(await saved.path());await page.reload();await page.locator('#file').setInputFiles({name:'font.ekopdf',mimeType:'application/json',buffer:project});await expect(page.locator('#busy')).toBeHidden();await expect(page.locator('#document')).toBeVisible();const r=read(await exported(page));expect(r.text).toContain('Çağrı Şen');expect(r.chars.every(c=>/Italic/.test(c.font))).toBe(true);});
test('embedded font reference survives reload and preserves rotated page',async({page})=>{await upload(page,await fixture({rotation:90}));await edit(page,'editable');await expect(page.locator('#fontstatus')).toContainText('korunuyor');const event=page.waitForEvent('download');await page.locator('#project').click();const dl=await event,project=await fs.readFile(await dl.path());await page.reload();await page.locator('#file').setInputFiles({name:'font.ekopdf',mimeType:'application/json',buffer:project});await expect(page.locator('#busy')).toBeHidden();const bytes=await exported(page);expect((await PDFDocument.load(bytes)).getPage(0).getRotation().angle).toBe(90);expect(read(bytes).text).toContain('editable');expect(read(bytes).chars.every(c=>/Italic/.test(c.font))).toBe(true);});
test('mixed fonts and sizes are separate editable runs',async({page})=>{await upload(page,await fixture({mixed:true}));await page.locator('#select').click();await page.locator('#edit').click();await expect(page.locator('[data-native]')).toHaveCount(2);await page.locator('[data-native="1"]').click();await expect(page.locator('#propsize')).toHaveValue('17');await edit(page,'BOLD');await expect(page.locator('#fontstatus')).toContainText('korunuyor');const r=read(await exported(page));const bold=r.chars.filter(c=>/Bold/.test(c.font));expect(bold.map(c=>c.c).join('')).toBe('BOLD');expect(bold.every(c=>Math.abs(c.size-17)<.01)).toBe(true);});
test('subset glyphs used on another page can be reused on the edited page',async({page})=>{const d=await PDFDocument.create();d.registerFontkit(fontkit);const font=await d.embedFont(await fs.readFile('C:/Windows/Fonts/timesi.ttf'),{subset:true});d.addPage([595,842]).drawText('Original text',{x:60,y:720,size:23,font});d.addPage([595,842]).drawText('ĞŞİ Çağrı',{x:60,y:720,size:23,font});await upload(page,Buffer.from(await d.save()));await edit(page,'Çağrı ĞŞİ');await expect(page.locator('#fontstatus')).toContainText('korunuyor');const r=read(await exported(page));expect(r.text).toContain('Çağrı ĞŞİ');expect(r.chars.every(c=>/TimesNewRomanPS-ItalicMT/.test(c.font))).toBe(true);});
